色露肩上衣，领口和袖口饰有精致蕾丝花边，胸前系着蝴蝶结，下摆微微收紧露出紫色腰带；脖子上戴着一条金色细链，坠着一枚椭圆形紫色宝石吊坠。她的右手轻轻捏住一朵紫色风铃草，花瓣舒展，花茎细长带有绿色叶片。柔和的金色阳光从左侧树叶间洒落，背景是朦胧的绿色树影与散景光点，整体画面呈现温暖、自然且梦幻的氛围。"],"color":"#232","bgcolor":"#353"},{"id":259,"type":"ConditioningZeroOut","pos":[7078.354216378727,173.97832058881875],"size":[140,26],"flags":{"collapsed":false},"order":42,"mode":0,"inputs":[{"label":"条件","localized_name":"条件","name":"conditioning","type":"CONDITIONING","link":281}],"outputs":[{"label":"条件","localized_name":"条件","name":"CONDITIONING","type":"CONDITIONING","links":[294,306,327]}],"properties":{"cnr_id":"comfy-core","ver":"0.9.2","Node name for S&R":"ConditioningZeroOut","ue_properties":{"version":"7.5.2","widget_ue_connectable":{},"input_ue_unconnectable":{}}},"widgets_values":[],"color":"#322","bgcolor":"#533"},{"id":266,"type":"VAELoader","pos":[6732.941223481578,-208.29753163769914],"size":[229.6846921988198,58],"flags":{},"order":2,"mode":0,"inputs":[{"localized_name":"vae名称","name":"vae_name","type":"COMBO","widget":{"name":"vae_name"},"link":null}],"outputs":[{"localized_name":"VAE","name":"VAE","type":"VAE","links":[297,309,328]}],"properties":{"cnr_id":"comfy-core","ver":"0.25.0","Node name for S&R":"VAELoader","ue_properties":{"widget_ue_connectable":{},"version":"7.8","input_ue_unconnectable":{}},"models":[{"name":"qwen_image_vae.safetensors","url":"https://huggingface.co/Comfy-Org/Krea-2/resolve/main/vae/qwen_image_vae.safetensors","directory":"vae"}]},"widgets_values":["qwen_image_vae.safetensors"],"color":"#323","bgcolor":"#535"},{"id":204,"type":"VAEDecode","pos":[7078.4662219723605,54.88925345541823],"size":[140,46],"flags":{"collapsed":false},"order":49,"mode":0,"inputs":[{"localized_name":"Latent","name":"samples","type":"LATENT","link":222},{"localized_name":"vae","name":"vae","type":"VAE","link":297}],"outputs":[{"localized_name":"图像","name":"IMAGE","type":"IMAGE","links":[298,330]}],"properties":{"cnr_id":"comfy-core","ver":"0.12.3","Node name for S&R":"VAEDecode","ue_properties":{